SELECT TblCase.CaseID, TblCase.Last_Name, TblCase.First_Name, TblCase.Address, TblCase.City, TblCase.State, TblCase.Zip, TblCase.DOB, TblCase.SSN, TblCase.HmPhone, TblCase.OtherPhone, TblCase.Email, TblCase.Comments, TblCase.Referral, TblCase.Closed, TblCase.Clsdate, [tblCase].[case_Letter] & [tblCase].[yr] & "-" & [Number_] & "-" & [tblCase].[Orig_Atty] AS CaseNo, Disposition.Dispo_Date, Disposition.DispoJudge, Disposition.Dispo_Atty, Disposition.DispoOppC, Disposition.[PI Settlement Amount], Disposition.Disposition, Disposition.[Total Earned Fee]
FROM TblCase INNER JOIN Disposition ON TblCase.CaseID = Disposition.CaseID;